            elif aapl_close > self.previous_closes[self.aapl]:
                self.aapl_red_streak = 0
            else:
                self.aapl_red_streak = 0
        else:
            self.aapl_red_streak = 0

        self.previous_closes[self.spy] = spy_close
        self.previous_closes[self.aapl] = aapl_close

        if self.IsWarmingUp:
            return

        if not (
            self.spy_sma_200.IsReady
            and self.spy_sma_50.IsReady
            and self.aapl_rsi_14.IsReady
        ):
            return

        spy_sma_200_current = self.spy_sma_200.Current.Value
        spy_sma_200_previous = self.spy_sma_200.Previous.Value
        spy_sma_50_current = self.spy_sma_50.Current.Value
        spy_sma_50_previous = self.spy_sma_50.Previous.Value

        spy_close_previous = self.previous_closes.get(self.spy)
        aapl_rsi_current = self.aapl_rsi_14.Current.Value

        if spy_close_previous is None:
