            spy_sell_reason = False

        if self.aapl in data.Bars:
            aapl_close = data.Bars[self.aapl].Close

            if self.prev_aapl_close is not None:
                if aapl_close < self.prev_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            aapl_buy_reason = self.aapl_red_streak >= 3
            aapl_sell_reason = (
                self.aapl_rsi_14.IsReady
                and self.aapl_rsi_14.Current.Value > 60
            )
        else:
            aapl_buy_reason = False
            aapl_sell_reason = False

        if self.IsWarmingUp:
            self._update_previous_values(data)
            return

        if not all(symbol in data.Bars for symbol in symbols):
            self._update_previous_values(data)
            return

        if self.spy_lot > 0 and spy_sell_reason:
            self.MarketOrder(self.spy, -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and aapl_sell_reason:
            self.MarketOrder(self.aapl, -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and spy_buy_reason:
            close = data.Bars[self.spy].Close
            target_value = self.Portfolio.TotalPortfolioValue * 0.40
            quantity = int(target_value / close)

            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and aapl_buy_reason:
            close = data.Bars[self.aapl].Close
            available_cash = self.Portfolio.Cash
            purchase_amount = 20000

            if available_cash >= purchase_amount:
                quantity = int(purchase_amount / close)

                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.aapl_lot = quantity

        self._update_previous_values(data)

    def _update_previous_values(self, data):
        if self.spy in data.Bars:
            self.prev_spy_close = data.Bars[self.spy].Close

            if self.spy_sma_200.IsReady:
                self.prev_spy_sma_200 = self.spy_sma_200.Current.Value

            if self.spy_sma_50.IsReady:
                self.prev_spy_sma_50 = self.spy_sma_50.Current.Value

        if self.aapl in data.Bars:
            self.prev_aapl_close = data.Bars[self.aapl].Close
